!function(p){function n(n){for(var t,e,i=n[0],c=n[1],m=n[2],u=0,j=[];u<i.length;u++)e=i[u],Object.prototype.hasOwnProperty.call(a,e)&&a[e]&&j.push(a[e][0]),a[e]=0;for(t in c)Object.prototype.hasOwnProperty.call(c,t)&&(p[t]=c[t]);for(s&&s(n);j.length;)j.shift()();return o.push.apply(o,m||[]),r()}function r(){for(var p,n=0;n<o.length;n++){for(var r,e=o[n],i=!0,c=1;c<e.length;c++)r=e[c],0!==a[r]&&(i=!1);i&&(o.splice(n--,1),p=t(t.s=e[0]))}return p}function t(n){if(e[n])return e[n].exports;var r=e[n]={i:n,l:!1,exports:{}};return p[n].call(r.exports,r,r.exports,t),r.l=!0,r.exports}var e={},a={5:0},o=[];t.m=p,t.c=e,t.d=function(p,n,r){t.o(p,n)||Object.defineProperty(p,n,{enumerable:!0,get:r})},t.r=function(p){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(p,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(p,"__esModule",{value:!0})},t.t=function(p,n){if(1&n&&(p=t(p)),8&n)return p;if(4&n&&"object"==typeof p&&p&&p.__esModule)return p;var r=Object.create(null);if(t.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:p}),2&n&&"string"!=typeof p)for(var e in p)t.d(r,e,function(n){return p[n]}.bind(null,e));return r},t.n=function(p){var n=p&&p.__esModule?function(){return p.default}:function(){return p};return t.d(n,"a",n),n},t.o=function(p,n){return Object.prototype.hasOwnProperty.call(p,n)},t.p="";var i=window.webpackJsonp=window.webpackJsonp||[],c=i.push.bind(i);i.push=n,i=i.slice();for(var m=0;m<i.length;m++)n(i[m]);var s=c;o.push([35,0]),r()}({35:function(p,n,r){"use strict";r.r(n);var t=r(0);Object(t.a)("jp","army",r(36),r(1))},36:function(p){p.exports=JSON.parse('{"category":[{"name":"日本","link":"jp_shortcut"},{"name":"陆战武器","link":"jp_army"},{"name":"火炮","link":"jp_army#jp_army_cannon"}],"model":"105毫米口径火炮","description":"<h6>综述：</h6><p>二战期间，日军装备有多种型号的105毫米口径火炮，类型包括榴弹炮和加农炮。其中，除了99式105毫米榴弹炮因重量较轻和射程较短而被日军称之为山炮外，其它各型号日军均称为野炮或野战加农炮。在众多105毫米口径的火炮中，除明治38式105毫米野炮（榴弹炮）在二战爆发时性能已严重落后外，其它型号在战场上的表现均都不错，很受日军步兵部队欢迎，成为战场上日军进行火力压制的重要武器。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/jp/army/jp_army_cannon105mm_11.jpg","description":"<h6>99式105毫米山炮</h6><p></p><p>基本技术数据：</p><p>口径：105毫米；</p><p>炮管长：1303毫米；</p><p>炮重：800公斤；</p><p>炮口初速：334米/秒；</p><p>最大射程：7500米；</p><p>弹种：爆破弹（12.34公斤）、杀伤榴弹、纵火弹、化学弹。</p><p>服役时间：1939年～1945年。</p><p></p><p>注：该炮重量较轻，机动性能较好，适用于多种地形作战，除了用作火力压制外，也可作为平射炮使用。其主要装备给日军精锐野战部队的步兵大队或野战师团的步兵联队，每个大队或联队一般装备4～8门，是日军重点生产的一种低成本火炮。</p>","caption":""},{"image":"imgs/jp/army/jp_army_cannon105mm_12.jpg","description":"<h6>明治38式105毫米野炮</h6><p></p><p>基本技术数据：</p><p>口径：105毫米；</p><p>炮管长：3325毫米；</p><p>炮重：2594公斤；</p><p>火炮高低射界：-2度～+15度；</p><p>炮口初速：540米/秒；</p><p>最大射程：10800米；</p><p>弹种：榴弹（18.0公斤）、纵火弹、化学弹。</p><p>服役时间：1931年～1945年。</p><p></p><p>注：该炮整体性能较差，在二战爆发时已显落后，但在日军的独立炮兵部队中，仍有一部分在二战期间参加了作战行动。</p>","caption":""},{"image":"imgs/jp/army/jp_army_cannon105mm_13.jpg","description":"<h6>91式105毫米野炮</h6><p></p><p>基本技术数据：</p><p>口径：105毫米；</p><p>炮管长：2090毫米；</p><p>炮重：1750公斤；</p><p>火炮高低射界：-5度～+43度；</p><p>炮口初速：454米/秒；</p><p>最大射程：10800米；</p><p>弹种：榴弹（15.76公斤）、纵火弹、化学弹。</p><p>服役时间：1931年～1945年。</p><p></p><p>注：该炮射程较远，有较大的杀伤威力，在战场上主要用作火力压制，后期还装在机动底盘上作为自行反坦克火炮用，在太平洋战场曾与美军M4坦克作战，该炮主要配属日军旅团以上的炮兵部队。</p>","caption":""},{"image":"imgs/jp/army/jp_army_cannon105mm_14.jpg","description":"<h6>大正十四年式105毫米野战加农炮</h6><p></p><p>基本技术数据：</p><p>口径：105毫米；</p><p>炮管长：3590毫米；</p><p>炮重：3115公斤；</p><p>火炮高低射界：-5度～+43度；</p><p>炮口初速：640米/秒；</p><p>最大射程：15300米；</p><p>弹种：榴弹（15.76公斤）、纵火弹、化学弹。</p><p>服役时间：1925年～1945年。</p><p></p><p>注：该炮作为日军早期生产的一种远程压制火力武器，主要装备步兵师、旅团下属炮兵部队和野战炮兵旅团，其射程超过15公里，炮弹超过15公斤，具有较强的远程压制火力，虽然炮型老旧，但仍一直使用到二战结束。</p>","caption":""},{"image":"imgs/jp/army/jp_army_cannon105mm_15.jpg","description":"<h6>92式105毫米野战加农炮</h6><p></p><p>基本技术数据：</p><p>口径：105毫米；</p><p>炮管长：4725毫米；</p><p>炮重：3730公斤；</p><p>火炮高低射界：-5度～+43度；</p><p>炮口初速：765米/秒；</p><p>最大射程：18200米；</p><p>弹种：榴弹（15.76公斤）、纵火弹、化学弹。</p><p>服役时间：1935年～1945年。</p><p></p><p>注：该炮炮管长、炮弹发射初速高，在日军的105毫米口径火炮中有着最远的射程，但该炮的缺点是重量大，因而主要部署在预设阵地上作为远程压制火力使用，多为野战炮兵部队使用。</p>","caption":""}],"part2title":"战场上的日军105毫米口径火炮","part2description":"","part2content":[{"image":"imgs/jp/army/jp_army_cannon105mm_21.jpg","description":"中国抗日战场上，日军一门99式105毫米山炮与其炮兵。","caption":""},{"image":"imgs/jp/army/jp_army_cannon105mm_22.jpg","description":"1942年2月，中国抗日战场，日军的一处野战炮阵地上，多门105毫米加农炮正在开炮射击。","caption":""},{"image":"imgs/jp/army/jp_army_cannon105mm_23.jpg","description":"1944年，东南亚战场，菲律宾，日军正在一门38式105毫米野炮的火力支援下，阻击进攻的美军。","caption":""},{"image":"imgs/jp/army/jp_army_cannon105mm_24.jpg","description":"中国抗日战场上，正在作战中的日军一处38式105毫米野炮阵地。","caption":""}]}')}});